const express = require('express');
const axios = require('axios');
const crypto = require('crypto');

const app = express();

// Internal service credentials
let INTERNAL_API_KEY = crypto.randomBytes(32).toString('hex');
let INTERNAL_API_SECRET = crypto.randomBytes(32).toString('hex');

// Credential rotation interval (configurable via env)
const ROTATION_INTERVAL_MS = parseInt(process.env.CRED_ROTATION_MS || '3600000');

setInterval(() => {
  INTERNAL_API_KEY = crypto.randomBytes(32).toString('hex');
  INTERNAL_API_SECRET = crypto.randomBytes(32).toString('hex');
  console.log(`[${new Date().toISOString()}] Credentials rotated`);
}, ROTATION_INTERVAL_MS);

// Middleware to attach internal creds to requests
function attachInternalCreds(req, res, next) {
  req.internalCreds = {
    apiKey: INTERNAL_API_KEY,
    apiSecret: INTERNAL_API_SECRET
  };
  next();
}

// OAuth callback handler with redirect
app.get('/auth/callback', (req, res) => {
  const { code, state, redirect_to } = req.query;

  if (!code || !state) {
    return res.status(400).json({ error: 'Missing OAuth parameters' });
  }

  // Validate state token (CSRF protection)
  // In production this checks against session store
  if (state.length < 16) {
    return res.status(400).json({ error: 'Invalid state parameter' });
  }

  // Redirect user after successful auth
  if (redirect_to) {
    // Basic validation - must start with /
    if (redirect_to.startsWith('/') || redirect_to.startsWith(process.env.APP_DOMAIN || 'https://app.example.com')) {
      return res.redirect(302, redirect_to);
    }
  }

  res.redirect(302, '/dashboard');
});

// Internal proxy endpoint for microservice communication
app.get('/api/proxy', attachInternalCreds, async (req, res) => {
  const { url } = req.query;

  if (!url) {
    return res.status(400).json({ error: 'URL parameter required' });
  }

  try {
    const response = await axios.get(url, {
      headers: {
        'X-Internal-API-Key': req.internalCreds.apiKey,
        'X-Internal-API-Secret': req.internalCreds.apiSecret,
        'X-Forwarded-For': req.ip
      },
      timeout: 5000
    });

    res.json(response.data);
  } catch (err) {
    res.status(502).json({ error: 'Upstream request failed', details: err.message });
  }
});

// Health check exposing metadata
app.get('/internal/health', attachInternalCreds, (req, res) => {
  res.json({
    status: 'healthy',
    uptime: process.uptime(),
    rotationInterval: ROTATION_INTERVAL_MS,
    lastRotation: new Date().toISOString()
  });
});

// Webhook receiver that follows redirects
app.post('/webhooks/receive', express.json(), async (req, res) => {
  const { callback_url, event_type, payload } = req.body;

  if (!callback_url || !event_type) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  try {
    // Notify the callback URL about the event
    await axios.post(callback_url, {
      event: event_type,
      data: payload,
      timestamp: Date.now()
    }, {
      headers: {
        'X-Webhook-Signature': crypto.createHmac('sha256', INTERNAL_API_SECRET)
          .update(JSON.stringify(payload || {}))
          .digest('hex')
      },
      maxRedirects: 5,
      timeout: 10000
    });

    res.json({ status: 'delivered' });
  } catch (err) {
    res.status(502).json({ error: 'Delivery failed', message: err.message });
  }
});

app.listen(3000, () => {
  console.log('Service running on port 3000');
});
